def primes():
    yield 2
    candidate = 3
    while True:
        is_prime = True
        i = 3
        while i * i <= candidate:
            if candidate % i == 0:
                is_prime = False
                break
            i += 2
        if is_prime:
            yield candidate
        candidate += 2

def first_n_primes(n):
    gen = primes()
    return [next(gen) for _ in range(n)]
